// THE INBOUND FORM WEBHOOK — the second source of record.
//
// Anything that can POST JSON can feed this: a HubSpot form, a Webflow or
// Framer form, a Typeform, a custom marketing site. The payload is normalised
// here, once, so the scoring pass never learns what a "Typeform answer" is.
//
// Field naming across form tools is not standardised and never will be, so this
// reads a small set of ALIASES per field rather than demanding a schema. What it
// will not do is guess: a payload with no recognisable email is rejected with a
// 422 naming the keys it saw, because a lead silently dropped at the door is the
// worst failure this product can have.

import type { Lead } from "@/app/_lib/types";
import { emailDomain } from "@/app/_lib/agent/guardrails";

const ALIAS: Record<string, string[]> = {
  email: ["email", "email_address", "emailaddress", "work_email", "e-mail", "your-email"],
  firstName: ["first_name", "firstname", "fname", "given_name", "first"],
  lastName: ["last_name", "lastname", "lname", "family_name", "surname", "last"],
  fullName: ["name", "full_name", "fullname", "your-name"],
  company: ["company", "company_name", "organisation", "organization", "org", "business"],
  title: ["title", "job_title", "jobtitle", "role", "position"],
  phone: ["phone", "phone_number", "telephone", "mobile", "tel"],
  message: ["message", "comments", "notes", "how_can_we_help", "what_are_you_looking_for", "body"],
  formName: ["form", "form_name", "formname", "form_id", "source", "formId"],
  website: ["website", "url", "company_website", "domain"],
};

type Payload = Record<string, unknown>;

/** Flatten one level of nesting — most form tools post either flat keys or a
 *  `{fields: {...}}` / `{data: {...}}` envelope. */
function flatten(payload: Payload): Payload {
  const out: Payload = { ...payload };
  for (const key of ["fields", "data", "answers", "properties", "submission"]) {
    const nested = payload[key];
    if (nested && typeof nested === "object" && !Array.isArray(nested)) {
      Object.assign(out, nested as Payload);
    }
  }
  // HubSpot's own form payload posts `fields: [{name, value}, …]`.
  const arr = payload.fields;
  if (Array.isArray(arr)) {
    for (const f of arr as { name?: string; value?: unknown }[]) {
      if (f?.name) out[f.name] = f.value;
    }
  }
  return out;
}

function pick(payload: Payload, field: keyof typeof ALIAS): string | null {
  const keys = Object.keys(payload);
  for (const alias of ALIAS[field]) {
    const key = keys.find((k) => k.toLowerCase().replace(/\s+/g, "_") === alias);
    if (key != null) {
      const v = payload[key];
      if (v == null) continue;
      const s = String(v).trim();
      if (s !== "") return s;
    }
  }
  return null;
}

export interface NormaliseResult {
  ok: true;
  lead: Omit<Lead, "id"> & { sourceId: string };
}
export interface NormaliseFailure {
  ok: false;
  /** Names the keys the payload actually carried, so a misconfigured form is
   *  diagnosable from the 422 alone. */
  error: string;
}

export function normaliseFormPost(
  raw: Payload,
  opts: { sourceId: string; now?: Date } ,
): NormaliseResult | NormaliseFailure {
  const payload = flatten(raw);
  const email = pick(payload, "email");
  if (!email || !email.includes("@")) {
    const keys = Object.keys(payload).slice(0, 20).join(", ") || "(empty body)";
    return {
      ok: false,
      error: `No email field found. Keys received: ${keys}. Post one of: ${ALIAS.email.join(", ")}.`,
    };
  }

  const full = pick(payload, "fullName");
  const first = pick(payload, "firstName") ?? (full ? full.split(/\s+/)[0] : null);
  const last =
    pick(payload, "lastName") ?? (full && full.split(/\s+/).length > 1 ? full.split(/\s+/).slice(1).join(" ") : null);

  const website = pick(payload, "website");
  const now = opts.now ?? new Date();

  return {
    ok: true,
    lead: {
      sourceId: opts.sourceId,
      crmContactId: null,
      email: email.toLowerCase(),
      firstName: first,
      lastName: last,
      company: pick(payload, "company"),
      domain: emailDomain(email) ?? hostOf(website),
      title: pick(payload, "title"),
      phone: pick(payload, "phone"),
      message: pick(payload, "message"),
      formName: pick(payload, "formName"),
      source: "form",
      // The form's own submission time is the watermark axis. A form tool that
      // posts late still lands in the right place in the queue.
      createdAt: now.toISOString(),
      ingestedAt: now.toISOString(),
      score: null,
      band: null,
      reasons: [],
      scoredAt: null,
      enrichment: null,
      enrichmentAttempts: 0,
      status: "new",
    },
  };
}

function hostOf(url: string | null): string | null {
  if (!url) return null;
  try {
    return new URL(url.startsWith("http") ? url : `https://${url}`).hostname.replace(/^www\./, "");
  } catch {
    return null;
  }
}
